//! Knowledge index (tier 0) generation.
//!
//! `INDEX.md` is a generated map of the knowledge hierarchy: the tier-1
//! summary files plus every tier-2 topic file, grouped by category. It is
//! regenerated by [`write_index`] whenever a hierarchical knowledge dir is
//! written to (see `KnowledgeDir::append_target` /
//! `KnowledgeDir::replace_section_target`), and created for the first time on a
//! flat directory by `loom knowledge sync`.

use super::read::read_knowledge_file;
use super::types::{KnowledgeFile, INDEX_FILENAME};
use anyhow::{Context, Result};
use std::fs;
use std::path::{Path, PathBuf};

/// Marker at the top of a generated `INDEX.md` so a human or agent knows not
/// to hand-edit it — edits are lost the next time the index is regenerated.
pub const GENERATED_MARKER: &str =
    "<!-- generated automatically on knowledge writes — do not edit by hand -->";

/// A single tier-2 topic file discovered under a category directory.
#[derive(Debug, Clone)]
pub struct TopicEntry {
    pub category: KnowledgeFile,
    pub slug: String,
    /// Absolute path on disk.
    pub path: PathBuf,
    /// First `# ` line, without the marker (falls back to the slug).
    pub title: String,
    /// First `> ` line, without the marker (empty if none).
    pub blurb: String,
    pub line_count: usize,
}

impl TopicEntry {
    /// Path of this topic relative to the knowledge root, e.g.
    /// `architecture/merge-flow.md`.
    pub fn relative_path(&self) -> PathBuf {
        PathBuf::from(self.category.dir_name()).join(format!("{}.md", self.slug))
    }
}

/// Turn a hyphen/underscore-separated slug into a title, e.g. `merge-flow` ->
/// `Merge Flow`.
pub fn title_case(slug: &str) -> String {
    slug.split(['-', '_'])
        .filter(|word| !word.is_empty())
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

/// Escape a value for a markdown table cell: a raw `|` would end the cell and
/// break the row, and titles/blurbs come from user-written topic files.
fn escape_cell(value: &str) -> String {
    value.replace('|', "\\|")
}

/// Keeping table entries short makes the generated index inexpensive to pull.
pub(crate) const MAX_BLURB_CHARS: usize = 80;

/// Preserve enough context to identify a topic without letting one description
/// dominate a retrieved index.
fn truncate_blurb(blurb: &str) -> String {
    let Some((limit, _)) = blurb.char_indices().nth(MAX_BLURB_CHARS) else {
        return blurb.to_string();
    };
    let truncated = match blurb[..limit]
        .char_indices()
        .rfind(|(_, character)| character.is_whitespace())
    {
        Some((end, _)) => blurb[..end].trim_end_matches(|character: char| {
            character.is_whitespace()
                || character.is_ascii_punctuation()
                || matches!(character, '—' | '–' | '―' | '…')
        }),
        None => &blurb[..limit],
    };

    format!("{truncated}…")
}

/// Extract the title (first `# ` line) and blurb (first `> ` line) from a
/// knowledge file's content, falling back to `fallback_title` / empty string.
fn extract_title_and_blurb(content: &str, fallback_title: &str) -> (String, String) {
    let title = content
        .lines()
        .find_map(|line| line.strip_prefix("# "))
        .map(|s| s.trim().to_string())
        .unwrap_or_else(|| fallback_title.to_string());
    let blurb = content
        .lines()
        .find_map(|line| line.strip_prefix("> "))
        .map(|s| s.trim().to_string())
        .unwrap_or_default();
    (title, truncate_blurb(&blurb))
}

/// Walk `<root>/<category>/*.md` for every [`KnowledgeFile`] category.
///
/// Skips non-`.md` entries, subdirectories, symlinks and other non-regular
/// entries, and dotfiles. A missing category directory is simply skipped, not
/// an error. Results are sorted by (category order as in [`KnowledgeFile::all`],
/// then slug).
pub fn scan_topics(root: &Path) -> Result<Vec<TopicEntry>> {
    let mut topics = Vec::new();

    for category in KnowledgeFile::all() {
        let dir = root.join(category.dir_name());
        if !fs::symlink_metadata(&dir).is_ok_and(|metadata| metadata.is_dir()) {
            continue;
        }

        let mut category_topics = Vec::new();
        let entries = fs::read_dir(&dir)
            .with_context(|| format!("Failed to read topic directory: {}", dir.display()))?;
        for entry in entries {
            let entry =
                entry.with_context(|| format!("Failed to read entry in {}", dir.display()))?;
            category_topics.extend(read_topic(root, *category, &entry)?);
        }

        category_topics.sort_by(|a, b| a.slug.cmp(&b.slug));
        topics.extend(category_topics);
    }

    Ok(topics)
}

/// The topic `entry` of `category`'s directory, or `None` for anything that is
/// not a visible regular `.md` file. A symlink or other non-regular entry is
/// never indexed, as in the catalog walker; `read_knowledge_file` would refuse
/// it anyway.
fn read_topic(
    root: &Path,
    category: KnowledgeFile,
    entry: &fs::DirEntry,
) -> Result<Option<TopicEntry>> {
    if !entry.file_type().is_ok_and(|kind| kind.is_file()) {
        return Ok(None);
    }
    let path = entry.path();
    let Some(file_name) = path.file_name().and_then(|n| n.to_str()) else {
        return Ok(None);
    };
    if file_name.starts_with('.') || !file_name.ends_with(".md") {
        return Ok(None);
    }

    let slug = file_name.trim_end_matches(".md").to_string();
    let bytes = read_knowledge_file(root, &Path::new(category.dir_name()).join(file_name))
        .with_context(|| format!("Failed to read topic file: {}", path.display()))?;
    let content = String::from_utf8_lossy(&bytes).into_owned();
    let (title, blurb) = extract_title_and_blurb(&content, &slug);
    Ok(Some(TopicEntry {
        category,
        slug,
        path,
        title,
        blurb,
        line_count: content.lines().count(),
    }))
}

/// Render the `INDEX.md` content for `root`. Does not write anything.
pub fn generate_index(root: &Path) -> Result<String> {
    let topics = scan_topics(root)?;
    let mut out = String::new();

    out.push_str(GENERATED_MARKER);
    out.push_str("\n\n# Knowledge Index\n\n");
    out.push_str(
        "> Read this index first, then only what it points to: the section for your area \
         in a tier-1 summary (`rg -n '^## ' <file>` lists them) and the tier-2 topics your \
         task touches. A specific question is cheaper to pull than to read — `loom \
         knowledge context --query \"...\"` returns the matching sections quoted.\n\n",
    );

    append_tier1_table(&mut out, root)?;
    append_topic_tables(&mut out, &topics);

    Ok(out)
}

/// One row per tier-1 summary file that exists on disk as a regular file.
fn append_tier1_table(out: &mut String, root: &Path) -> Result<()> {
    out.push_str("## Tier 1 — Summaries\n\n");
    out.push_str("| File | Description | Lines |\n");
    out.push_str("| --- | --- | --- |\n");
    for file_type in KnowledgeFile::all() {
        let is_regular = fs::symlink_metadata(root.join(file_type.filename()))
            .is_ok_and(|metadata| metadata.file_type().is_file());
        if !is_regular {
            continue;
        }
        let bytes = read_knowledge_file(root, Path::new(file_type.filename()))
            .with_context(|| format!("Failed to read {}", file_type.filename()))?;
        let line_count = String::from_utf8_lossy(&bytes).lines().count();
        out.push_str(&format!(
            "| [{name}]({name}) | {desc} | {line_count} |\n",
            name = file_type.filename(),
            desc = file_type.description(),
        ));
    }
    Ok(())
}

/// One table per category, in the order `scan_topics` returned them. The
/// link text is the slug alone; the blurb carries what the title used to, so
/// a separate Title column would only repeat it.
fn append_topic_tables(out: &mut String, topics: &[TopicEntry]) {
    if topics.is_empty() {
        return;
    }
    out.push_str("\n## Tier 2 — Topics\n\n");
    let mut current_category: Option<KnowledgeFile> = None;
    for topic in topics {
        if current_category != Some(topic.category) {
            // Blank line between the previous category's table and this heading:
            // markdownlint (MD022/MD058) rejects a heading or table without one.
            if current_category.is_some() {
                out.push('\n');
            }
            out.push_str(&format!("### {}\n\n", topic.category.dir_name()));
            out.push_str("| Topic | Blurb | Lines |\n");
            out.push_str("| --- | --- | --- |\n");
            current_category = Some(topic.category);
        }
        let rel = topic.relative_path().display().to_string();
        out.push_str(&format!(
            "| [{}]({rel}) | {} | {} |\n",
            topic.slug,
            escape_cell(&topic.blurb),
            topic.line_count
        ));
    }
}

/// Whether `<root>/INDEX.md` differs from what [`generate_index`] renders. A
/// missing or unreadable index is an error; callers decide if it may be absent.
/// The read is bounded and refuses a symlink or non-regular file.
pub fn index_is_stale(root: &Path) -> Result<bool> {
    let actual = read_knowledge_file(root, Path::new(INDEX_FILENAME))
        .context("knowledge INDEX.md is missing or unreadable; run loom knowledge sync")?;
    Ok(actual != generate_index(root)?.as_bytes())
}

/// Crash-atomically write `<root>/INDEX.md`.
///
/// Generation, the comparison with the existing file and the publish all run
/// under the directory lock, so a writer that waited for the lock renders the
/// tree the previous lock holder left, never an older one.
pub fn write_index(root: &Path) -> Result<()> {
    let path = root.join(INDEX_FILENAME);
    crate::fs::locking::locked_dir_update(root, || {
        let content = generate_index(root)?;
        // A refused read (symlink, FIFO, oversized, unreadable) counts as
        // "differs": the write replaces whatever occupies the name.
        let current = read_knowledge_file(root, Path::new(INDEX_FILENAME));
        if current.is_ok_and(|existing| existing == content.as_bytes()) {
            return Ok(());
        }
        crate::fs::locking::atomic_write_locked(&path, &content)
    })
    .with_context(|| format!("Failed to write {}", path.display()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn test_title_case() {
        assert_eq!(title_case("merge-flow"), "Merge Flow");
        assert_eq!(title_case("signal_prefix_cache"), "Signal Prefix Cache");
        assert_eq!(title_case("solo"), "Solo");
    }

    #[test]
    fn test_scan_topics_reads_title_blurb_and_ignores_non_markdown() {
        let temp = TempDir::new().unwrap();
        let root = temp.path();
        let arch_dir = root.join("architecture");
        fs::create_dir_all(&arch_dir).unwrap();
        fs::write(
            arch_dir.join("merge-flow.md"),
            "# Merge Flow\n\n> How stages merge back to the base branch.\n\nBody line.\n",
        )
        .unwrap();
        // Non-markdown file must be ignored.
        fs::write(arch_dir.join("notes.txt"), "ignore me").unwrap();
        // Dotfile must be ignored.
        fs::write(arch_dir.join(".hidden.md"), "# Hidden\n").unwrap();

        let topics = scan_topics(root).unwrap();
        assert_eq!(topics.len(), 1);
        let topic = &topics[0];
        assert_eq!(topic.slug, "merge-flow");
        assert_eq!(topic.title, "Merge Flow");
        assert_eq!(topic.blurb, "How stages merge back to the base branch.");
        assert_eq!(topic.line_count, 5);
    }

    #[test]
    fn test_scan_topics_skips_missing_category_dir() {
        let temp = TempDir::new().unwrap();
        let topics = scan_topics(temp.path()).unwrap();
        assert!(topics.is_empty());
    }

    /// Long prose must not make a single index row crowd out other topics.
    #[test]
    fn test_truncate_blurb_uses_word_boundary_and_ellipsis() {
        let blurb = format!("{}extra", "word, ".repeat(20));
        let truncated = truncate_blurb(&blurb);

        assert_eq!(truncated, format!("{}word…", "word, ".repeat(12)));
        assert!(truncated.ends_with('…'));
        assert!(truncated.chars().count() <= MAX_BLURB_CHARS + 1);
    }

    /// A full-sized concise description should not lose useful detail.
    #[test]
    fn test_truncate_blurb_preserves_exactly_max_blurb_chars() {
        let blurb = "x".repeat(MAX_BLURB_CHARS);
        assert_eq!(truncate_blurb(&blurb), blurb);
    }

    /// Author-written Unicode must never turn a character limit into a bad slice.
    #[test]
    fn test_truncate_blurb_handles_multibyte_character_after_limit() {
        let blurb = format!("{}é beyond the limit", "x".repeat(MAX_BLURB_CHARS));
        assert_eq!(
            truncate_blurb(&blurb),
            format!("{}…", "x".repeat(MAX_BLURB_CHARS))
        );
    }
}

